        {
          id: "ceramic-set",
          name: "Stackable ceramic set",
          category: "Kitchen",
          price: "$52",
          rating: "4.7",
          swatch: "#cfd8e8",
        },
        {
          id: "cotton-robe",
          name: "Cloud cotton robe",
          category: "Wellness",
          price: "$84",
          rating: "4.9",
          swatch: "#eadfd2",
        },
      ];

      const stories = [
        {
          title: "How to build a calmer morning routine",
          meta: "Style guide · 5 minute read",
          text: "Layer soft textures, practical organizers, and scent notes that make weekday starts feel considered.",
          swatch: "#d7e3ca",
        },
        {
          title: "A buyer's guide to gifts that last",
          meta: "Editorial picks · New",
          text: "Our merchandisers share durable favorites for hosts, new homes, and everyday rituals.",
          swatch: "#f5d2bd",
        },
      ];

      const escapeHtml = (value) =>
        String(value).replace(/[&<>"']/g, (character) => {
          const entities = {
            "&": "&amp;",
            "<": "&lt;",
            ">": "&gt;",
            '"': "&quot;",
            "'": "&#039;",
          };
          return entities[character];
        });

      function Header() {
        return `
          <header class="site-header">
            <div class="header-inner">
              <a class="brand" href="#" aria-label="Northline Goods home">
                <span class="brand-mark" aria-hidden="true">NG</span>
                <span>Northline Goods</span>
              </a>
              <nav class="primary-nav" aria-label="Primary">
                <ul>
                  <li><a href="#featured" aria-current="page">Featured</a></li>
                  <li><a href="#deals">Deals</a></li>
                  <li><a href="#editorial">Editorial</a></li>
                  <li><a href="#newsletter">Newsletter</a></li>
                </ul>
              </nav>
              <div class="header-actions">
                <span class="cart-pill" aria-label="Cart with 0 items">
                  <span aria-hidden="true">Bag</span>
                  <span id="cart-count">0</span>
                </span>
              </div>
            </div>
          </header>
        `;
      }

      function Hero() {
        return `
          <section class="section hero" aria-labelledby="hero-heading">
            <div class="hero-grid">
              <div>
                <span class="eyebrow">New season edit</span>
                <h1 id="hero-heading">Made for modern living</h1>
                <p>
                  Shop refined home goods, versatile accessories, and thoughtful
                  staples curated for a cleaner daily routine.
                </p>
                <div class="button-row">
                  <a class="button button-primary" href="#featured">Shop featured products</a>
                  <a class="button button-secondary" href="#editorial">Read the edit</a>
                </div>
              </div>
              <div class="hero-card">
                <div class="product-stack">
                  <div class="floating-product" style="--swatch: #dbe7d4">
                    <span class="product-swatch" aria-hidden="true"></span>
                    <span><strong>Soft goods</strong><span>Textiles in warm neutrals</span></span>
                  </div>
                  <div class="floating-product" style="--swatch: #f2c9a8">
                    <span class="product-swatch" aria-hidden="true"></span>
                    <span><strong>Carry essentials</strong><span>Lightweight pieces for every errand</span></span>
                  </div>
                </div>
              </div>
            </div>
          </section>
        `;
      }

      function ProductCard(product) {
        const name = escapeHtml(product.name);
        return `
          <li>
            <article class="product-card">
              <div class="product-art" style="--swatch: ${escapeHtml(product.swatch)}" aria-hidden="true"></div>
              <div class="product-body">
                <p class="product-meta">${escapeHtml(product.category)}</p>
                <h3><a href="#${escapeHtml(product.id)}">${name}</a></h3>
                <div class="price-row">
                  <span class="price">${escapeHtml(product.price)}</span>
                  <span class="rating" aria-label="Rated ${escapeHtml(product.rating)} out of 5">${escapeHtml(product.rating)} ★</span>
