                <button class="button add-button" type="button" data-product="${name}" aria-label="Add to cart: ${name}">
                  Add to cart
                </button>
              </div>
            </article>
          </li>
        `;
      }

      function FeaturedProducts() {
        return `
          <section class="section" id="featured" aria-labelledby="featured-heading">
            <div class="section-header">
              <div>
                <span class="eyebrow">Featured products</span>
                <h2 id="featured-heading">Best of the week</h2>
