          </section>
        `;
      }

      function Deals() {
        return `
          <section class="section" id="deals" aria-labelledby="deals-heading">
            <div class="section-header">
              <div>
                <span class="eyebrow">Limited deals</span>
                <h2 id="deals-heading">Smart savings</h2>
              </div>
              <p>Rotating offers on high-quality essentials, with clear pricing and no code hunting.</p>
            </div>
            <div class="deal-grid">
              <article class="deal-card featured">
                <span class="deal-badge">Up to 30% off</span>
                <div>
                  <h3>Weekend home reset</h3>
                  <p>Bundle textiles, tableware, and pantry organizers for an instant refresh.</p>
                  <a class="button button-secondary" href="#featured">Shop the bundle</a>
                </div>
              </article>
              <div class="deal-stack">
                <article class="deal-card mini-deal">
                  <span class="deal-badge">Buy more, save more</span>
                  <div>
                    <h3>Kitchen staples</h3>
                    <p>Save 15% when you choose any three dining or prep essentials.</p>
                    <a href="#featured">Browse kitchen products</a>
