      }

      function Editorial() {
        return `
          <section class="section" id="editorial" aria-labelledby="editorial-heading">
            <div class="section-header">
              <div>
                <span class="eyebrow">Editorial</span>
                <h2 id="editorial-heading">Ideas worth keeping</h2>
              </div>
              <p>Shop with more context through guides, interviews, and practical styling notes.</p>
            </div>
            <div class="editorial-grid">
              ${stories.map(StoryCard).join("")}
              <aside class="newsletter-card" id="newsletter" aria-labelledby="newsletter-heading">
                <div>
                  <span class="eyebrow">Insider list</span>
                  <h3 id="newsletter-heading">Get the Sunday edit</h3>
                  <p>Weekly product drops, deal alerts, and practical home inspiration.</p>
                </div>
                <form class="newsletter-form" aria-describedby="newsletter-help">
                  <div class="field">
