      .hero-card {
        position: relative;
        overflow: hidden;
        min-height: 34rem;
        border: 1px solid rgba(222, 216, 204, 0.82);
        border-radius: var(--radius-lg);
        background:
          linear-gradient(150deg, rgba(24, 77, 59, 0.1), transparent 46%),
          var(--surface);
        box-shadow: var(--shadow);
