      .hero-card::after {
        width: 18rem;
        height: 18rem;
        left: -5rem;
        bottom: -4rem;
        background: #dbe7d4;
      }

      .product-stack {
        position: absolute;
        inset: 2rem;
        display: grid;
        align-content: end;
        gap: 1rem;
