      .floating-product strong,
      .floating-product span {
        display: block;
      }

      .floating-product span {
        color: var(--muted);
      }

      .section {
        padding-block: clamp(2.75rem, 6vw, 5rem);
      }

      .section-header {
        display: flex;
        align-items: end;
        justify-content: space-between;
        gap: 1rem;
        margin-bottom: 1.35rem;
      }

      .section-header h2 {
        margin: 0;
        font-size: clamp(2rem, 4vw, 3.4rem);
        line-height: 1;
        letter-spacing: -0.06em;
      }

      .section-header p {
        max-width: 34rem;
        margin: 0;
        color: var(--muted);
      }

      .product-grid,
      .deal-grid,
      .editorial-grid {
        display: grid;
        gap: 1rem;
      }

      .product-grid {
        grid-template-columns: repeat(4, minmax(0, 1fr));
        margin: 0;
        padding: 0;
        list-style: none;
      }

      .product-card,
      .deal-card,
      .story-card,
      .newsletter-card {
        border: 1px solid rgba(222, 216, 204, 0.9);
        border-radius: var(--radius-md);
        background: rgba(255, 255, 255, 0.72);
        box-shadow: 0 12px 44px rgba(28, 35, 31, 0.07);
