      .product-card {
        display: grid;
        gap: 0.9rem;
        padding: 0.8rem;
      }

      .product-art {
        display: grid;
        min-height: 13rem;
        place-items: center;
        overflow: hidden;
        border-radius: 1rem;
        background:
          radial-gradient(circle at 50% 40%, rgba(255, 255, 255, 0.78), transparent 30%),
          var(--swatch, #dbe7d4);
      }

      .product-art::before {
        content: "";
        width: 44%;
        aspect-ratio: 0.78;
        border-radius: 999px 999px 1.1rem 1.1rem;
        background: rgba(23, 32, 29, 0.1);
        box-shadow:
          1.25rem 1.1rem 0 rgba(255, 255, 255, 0.38),
          -1rem 1.6rem 0 rgba(23, 32, 29, 0.07);
      }

      .product-body {
        display: grid;
        gap: 0.45rem;
        padding: 0 0.2rem 0.2rem;
      }

      .product-card h3,
      .deal-card h3,
      .story-card h3 {
        margin: 0;
        font-size: 1.1rem;
        line-height: 1.2;
      }

      .product-card h3 a,
      .story-card h3 a {
        text-decoration-thickness: 0.08em;
      }

      .product-meta,
      .story-meta {
        color: var(--muted);
        font-size: 0.95rem;
      }

      .price-row {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 0.75rem;
      }

      .price {
        font-size: 1.1rem;
        font-weight: 950;
      }

      .rating {
        color: var(--brand);
        font-size: 0.9rem;
        font-weight: 850;
      }

      .add-button {
        width: 100%;
        border: 0;
        background: var(--ink);
        color: #fff;
      }

      .add-button:hover {
        background: #000;
      }

      .deal-grid {
        grid-template-columns: 1.1fr 0.9fr;
      }

      .deal-card {
        position: relative;
        overflow: hidden;
        min-height: 24rem;
        padding: clamp(1.25rem, 3vw, 2rem);
      }

      .deal-card.featured {
        display: grid;
        align-content: end;
        background:
          linear-gradient(135deg, rgba(24, 77, 59, 0.92), rgba(13, 56, 43, 0.92)),
          var(--brand);
        color: #fff;
      }

      .deal-card.featured p,
      .deal-card.featured .deal-note {
        color: rgba(255, 255, 255, 0.84);
      }

      .deal-card h3 {
        max-width: 12ch;
        font-size: clamp(2.1rem, 5vw, 4.8rem);
        letter-spacing: -0.07em;
      }

      .deal-card p {
        max-width: 30rem;
        color: var(--muted);
        font-size: 1.05rem;
      }

      .deal-stack {
        display: grid;
        gap: 1rem;
      }

      .mini-deal {
        display: grid;
        min-height: 11.5rem;
        align-content: space-between;
      }

      .deal-badge {
        display: inline-flex;
        width: fit-content;
        border-radius: 999px;
        background: var(--accent-soft);
        padding: 0.45rem 0.65rem;
        color: #78310f;
        font-size: 0.82rem;
        font-weight: 950;
        letter-spacing: 0.06em;
        text-transform: uppercase;
      }

      .featured .deal-badge {
        background: rgba(255, 255, 255, 0.16);
        color: #fff;
      }

      .deal-note {
        margin-top: 1rem;
        color: var(--muted);
        font-weight: 800;
      }

      .editorial-grid {
        grid-template-columns: 1fr 1fr 0.82fr;
        align-items: stretch;
      }

      .story-card {
        overflow: hidden;
      }

      .story-art {
        min-height: 16rem;
        background:
          linear-gradient(135deg, rgba(255, 255, 255, 0.68), transparent),
          var(--swatch, #dbe7d4);
      }

      .story-body,
      .newsletter-card {
        display: grid;
        gap: 0.75rem;
        padding: 1.15rem;
      }

      .story-card h3 {
        font-size: 1.45rem;
        letter-spacing: -0.04em;
      }

      .story-card p,
      .newsletter-card p {
        margin: 0;
        color: var(--muted);
      }

      .newsletter-card {
        align-content: space-between;
        background: var(--surface-soft);
      }

      .newsletter-card h3 {
        margin: 0;
        font-size: 1.8rem;
        line-height: 1.05;
        letter-spacing: -0.05em;
      }

      .newsletter-form {
        display: grid;
        gap: 0.75rem;
      }

      .field {
        display: grid;
        gap: 0.4rem;
      }

      .field label {
        font-weight: 850;
      }

      .field input {
        width: 100%;
        min-height: 48px;
        border: 1px solid var(--line);
        border-radius: 999px;
        background: #fff;
        color: var(--ink);
        padding: 0.8rem 1rem;
        font: inherit;
      }

      .form-help {
        color: var(--muted);
        font-size: 0.9rem;
      }

      .site-footer {
        margin-top: 2rem;
        border-top: 1px solid var(--line);
        background: var(--surface);
      }

      .footer-inner {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        padding-block: 1.5rem;
      }

      .footer-nav a {
        display: inline-flex;
        min-height: 44px;
        align-items: center;
        border-radius: 999px;
        padding: 0.55rem 0.75rem;
        color: var(--muted);
        font-weight: 750;
      }

      .status {
        position: fixed;
        right: 1rem;
        bottom: 1rem;
        z-index: 8;
        max-width: min(24rem, calc(100% - 2rem));
        border: 1px solid var(--line);
        border-radius: 999px;
        background: var(--surface);
        box-shadow: var(--shadow);
        padding: 0.8rem 1rem;
        font-weight: 850;
      }

      .status:empty {
        display: none;
      }

      @media (prefers-reduced-motion: reduce) {
        html {
          scroll-behavior: auto;
        }
      }

      @media (forced-colors: active) {
        .site-header,
        .product-card,
        .deal-card,
        .story-card,
        .newsletter-card,
        .cart-pill,
        .floating-product,
        .hero-card {
          border: 1px solid CanvasText;
          box-shadow: none;
        }

        .button,
        .add-button,
        .brand-mark {
          border: 1px solid ButtonText;
        }
      }

      @media (max-width: 940px) {
        .header-inner {
          align-items: flex-start;
          flex-wrap: wrap;
        }

        .primary-nav {
          order: 3;
          width: 100%;
        }

        .primary-nav ul {
          overflow-x: auto;
          padding-bottom: 0.2rem;
        }

        .hero-grid,
        .deal-grid,
        .editorial-grid {
          grid-template-columns: 1fr;
        }

        .hero-card {
          min-height: 28rem;
        }

        .product-grid {
          grid-template-columns: repeat(2, minmax(0, 1fr));
        }
      }

      @media (max-width: 620px) {
        .header-inner,
        .section,
        .footer-inner {
          width: min(100% - 1rem, var(--max));
        }

        .header-actions {
          width: 100%;
        }

        .cart-pill {
          justify-content: center;
          width: 100%;
        }

        .section-header,
        .footer-inner {
          align-items: stretch;
          flex-direction: column;
        }

        .product-grid {
          grid-template-columns: 1fr;
        }

        .hero-card {
          min-height: 23rem;
        }

        .product-stack {
          inset: 1rem;
        }

        .floating-product {
          grid-template-columns: 3.5rem 1fr;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>
    <div id="app"></div>
    <div class="status" id="cart-status" aria-live="polite" aria-atomic="true"></div>

    <script>
      const featuredProducts = [
        {
          id: "linen-throw",
          name: "Washed linen throw",
          category: "Home",
          price: "$68",
          rating: "4.9",
          swatch: "#dbe7d4",
        },
        {
          id: "trail-tote",
          name: "Everyday trail tote",
          category: "Accessories",
          price: "$46",
          rating: "4.8",
          swatch: "#f2c9a8",
        },
        {
          id: "ceramic-set",
          name: "Stackable ceramic set",
          category: "Kitchen",
          price: "$52",
          rating: "4.7",
          swatch: "#cfd8e8",
        },
        {
          id: "cotton-robe",
          name: "Cloud cotton robe",
          category: "Wellness",
          price: "$84",
          rating: "4.9",
          swatch: "#eadfd2",
        },
      ];

      const stories = [
        {
          title: "How to build a calmer morning routine",
          meta: "Style guide · 5 minute read",
          text: "Layer soft textures, practical organizers, and scent notes that make weekday starts feel considered.",
          swatch: "#d7e3ca",
        },
        {
          title: "A buyer's guide to gifts that last",
          meta: "Editorial picks · New",
          text: "Our merchandisers share durable favorites for hosts, new homes, and everyday rituals.",
          swatch: "#f5d2bd",
        },
      ];

      const escapeHtml = (value) =>
        String(value).replace(/[&<>"']/g, (character) => {
          const entities = {
            "&": "&amp;",
            "<": "&lt;",
            ">": "&gt;",
            '"': "&quot;",
            "'": "&#039;",
          };
          return entities[character];
        });

      function Header() {
        return `
          <header class="site-header">
            <div class="header-inner">
              <a class="brand" href="#" aria-label="Northline Goods home">
                <span class="brand-mark" aria-hidden="true">NG</span>
                <span>Northline Goods</span>
              </a>
              <nav class="primary-nav" aria-label="Primary">
                <ul>
                  <li><a href="#featured" aria-current="page">Featured</a></li>
                  <li><a href="#deals">Deals</a></li>
                  <li><a href="#editorial">Editorial</a></li>
                  <li><a href="#newsletter">Newsletter</a></li>
                </ul>
              </nav>
              <div class="header-actions">
                <span class="cart-pill" aria-label="Cart with 0 items">
                  <span aria-hidden="true">Bag</span>
                  <span id="cart-count">0</span>
                </span>
              </div>
            </div>
          </header>
        `;
      }

      function Hero() {
        return `
          <section class="section hero" aria-labelledby="hero-heading">
            <div class="hero-grid">
              <div>
                <span class="eyebrow">New season edit</span>
                <h1 id="hero-heading">Made for modern living</h1>
                <p>
                  Shop refined home goods, versatile accessories, and thoughtful
                  staples curated for a cleaner daily routine.
                </p>
                <div class="button-row">
                  <a class="button button-primary" href="#featured">Shop featured products</a>
                  <a class="button button-secondary" href="#editorial">Read the edit</a>
                </div>
              </div>
              <div class="hero-card">
                <div class="product-stack">
                  <div class="floating-product" style="--swatch: #dbe7d4">
                    <span class="product-swatch" aria-hidden="true"></span>
                    <span><strong>Soft goods</strong><span>Textiles in warm neutrals</span></span>
                  </div>
                  <div class="floating-product" style="--swatch: #f2c9a8">
                    <span class="product-swatch" aria-hidden="true"></span>
                    <span><strong>Carry essentials</strong><span>Lightweight pieces for every errand</span></span>
                  </div>
                </div>
              </div>
            </div>
          </section>
        `;
      }

      function ProductCard(product) {
        const name = escapeHtml(product.name);
        return `
          <li>
            <article class="product-card">
              <div class="product-art" style="--swatch: ${escapeHtml(product.swatch)}" aria-hidden="true"></div>
              <div class="product-body">
                <p class="product-meta">${escapeHtml(product.category)}</p>
                <h3><a href="#${escapeHtml(product.id)}">${name}</a></h3>
                <div class="price-row">
                  <span class="price">${escapeHtml(product.price)}</span>
                  <span class="rating" aria-label="Rated ${escapeHtml(product.rating)} out of 5">${escapeHtml(product.rating)} ★</span>
                </div>
                <button class="button add-button" type="button" data-product="${name}" aria-label="Add to cart: ${name}">
                  Add to cart
                </button>
              </div>
            </article>
          </li>
        `;
      }

      function FeaturedProducts() {
        return `
          <section class="section" id="featured" aria-labelledby="featured-heading">
            <div class="section-header">
              <div>
                <span class="eyebrow">Featured products</span>
                <h2 id="featured-heading">Best of the week</h2>
              </div>
              <p>Fresh arrivals selected for quality materials, smart utility, and effortless styling.</p>
            </div>
            <ul class="product-grid">
              ${featuredProducts.map(ProductCard).join("")}
            </ul>
          </section>
        `;
      }

      function Deals() {
        return `
          <section class="section" id="deals" aria-labelledby="deals-heading">
            <div class="section-header">
              <div>
                <span class="eyebrow">Limited deals</span>
                <h2 id="deals-heading">Smart savings</h2>
              </div>
              <p>Rotating offers on high-quality essentials, with clear pricing and no code hunting.</p>
            </div>
            <div class="deal-grid">
              <article class="deal-card featured">
                <span class="deal-badge">Up to 30% off</span>
                <div>
                  <h3>Weekend home reset</h3>
                  <p>Bundle textiles, tableware, and pantry organizers for an instant refresh.</p>
                  <a class="button button-secondary" href="#featured">Shop the bundle</a>
                </div>
              </article>
              <div class="deal-stack">
                <article class="deal-card mini-deal">
                  <span class="deal-badge">Buy more, save more</span>
                  <div>
                    <h3>Kitchen staples</h3>
                    <p>Save 15% when you choose any three dining or prep essentials.</p>
                    <a href="#featured">Browse kitchen products</a>
                  </div>
                </article>
                <article class="deal-card mini-deal">
                  <span class="deal-badge">Free shipping</span>
                  <div>
                    <h3>Orders over $75</h3>
                    <p class="deal-note">Automatically applied at checkout.</p>
                    <a href="#featured">Start shopping</a>
                  </div>
                </article>
              </div>
            </div>
          </section>
        `;
      }

      function StoryCard(story) {
        return `
          <article class="story-card">
            <div class="story-art" style="--swatch: ${escapeHtml(story.swatch)}" aria-hidden="true"></div>
            <div class="story-body">
              <p class="story-meta">${escapeHtml(story.meta)}</p>
              <h3><a href="#editorial">${escapeHtml(story.title)}</a></h3>
              <p>${escapeHtml(story.text)}</p>
            </div>
          </article>
        `;
      }

      function Editorial() {
        return `
          <section class="section" id="editorial" aria-labelledby="editorial-heading">
            <div class="section-header">
              <div>
                <span class="eyebrow">Editorial</span>
                <h2 id="editorial-heading">Ideas worth keeping</h2>
              </div>
              <p>Shop with more context through guides, interviews, and practical styling notes.</p>
            </div>
            <div class="editorial-grid">
              ${stories.map(StoryCard).join("")}
              <section class="newsletter-card" id="newsletter" aria-labelledby="newsletter-heading">
                <div>
                  <span class="eyebrow">Insider list</span>
                  <h3 id="newsletter-heading">Get the Sunday edit</h3>
                  <p>Weekly product drops, deal alerts, and practical home inspiration.</p>
                </div>
                <form class="newsletter-form" aria-describedby="newsletter-help">
                  <div class="field">
                    <label for="email">Email address <span aria-hidden="true">*</span></label>
                    <input id="email" name="email" type="email" autocomplete="email" required aria-describedby="newsletter-help" placeholder="you@example.com">
                    <span class="form-help" id="newsletter-help">Required. We only send one email per week.</span>
                  </div>
                  <button class="button button-primary" type="submit">Sign up for the Sunday edit</button>
                </form>
              </section>
            </div>
          </section>
        `;
      }

      function Footer() {
        return `
          <footer class="site-footer">
            <div class="footer-inner">
              <p><strong>Northline Goods</strong> · Thoughtful retail for everyday rituals.</p>
              <nav class="footer-nav" aria-label="Footer">
                <ul>
                  <li><a href="#featured">Shop</a></li>
                  <li><a href="#deals">Deals</a></li>
                  <li><a href="#editorial">Journal</a></li>
                  <li><a href="#newsletter">Contact</a></li>
                </ul>
              </nav>
            </div>
          </footer>
        `;
      }

      function App() {
        return `
          ${Header()}
          <main id="maincontent" tabindex="-1">
