const axeSource = require('axe-core').source;

(async () => {
  const html = fs.readFileSync(path.resolve('index.html'), 'utf8');
  const browser = await chromium.launch();
  const resultsByViewport = [];

  for (const viewport of [
    { width: 1280, height: 900, label: 'desktop' },
    { width: 320, height: 900, label: 'narrow' },
  ]) {
    const page = await browser.newPage({ viewport });
    await page.setContent(html, { waitUntil: 'load' });
    await page.addScriptTag({ content: axeSource });
    const axe = await page.evaluate(async () => window.axe.run());
    const brokenFragments = await page.evaluate(() => Array.from(document.querySelectorAll('a[href^="#"]'))
      .map((anchor) => anchor.getAttribute('href'))
      .filter(Boolean)
      .filter((href) => !document.getElementById(CSS.escape(decodeURIComponent(href.slice(1))))));
    await page.close();

    const wcag = axe.violations.filter((v) => !v.tags.includes('best-practice'));
    const bp = axe.violations.filter((v) => v.tags.includes('best-practice'));
    resultsByViewport.push({
      viewport: viewport.label,
      wcag: wcag.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) })),
      bp: bp.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) })),
      brokenFragments,
    });
  }

  await browser.close();
  console.log(JSON.stringify(resultsByViewport, null, 2));
  const failed = resultsByViewport.some((result) => result.wcag.length || result.bp.length || result.brokenFragments.length);
  process.exit(failed ? 1 : 0);
})().catch((error) => {
  console.error(error.stack || error.message);
  process.exit(2);
});
